import {advanceTime} from './routine.js';
export const MANAGER={x:0,z:-2},MACHINE={x:-1.25,z:-2.25},TABLE={x:-2.3,z:-.7};
export const ORDERS=[{name:'Maya',drink:'Latte'},{name:'Theo',drink:'Espresso'}];
export function normalizeCafe(v={}){const stage=['off','order','brew','serve','clean','clockout'].includes(v?.stage)?v.stage:'off';return {employed:v?.employed===true,stage,customer:Number.isInteger(v?.customer)?Math.max(0,Math.min(1,v.customer)):0,day:Number.isInteger(v?.day)?Math.max(0,v.day):0,paidDay:Number.isInteger(v?.paidDay)?Math.max(0,v.paidDay):0,served:Number.isInteger(v?.served)?Math.max(0,Math.min(2,v.served)):0}}
export function cafeTask(s){const c=normalizeCafe(s.cafe);if(c.stage==='off')return {...MANAGER,title:c.employed?'Talk to manager · clock in':'Talk to manager · apply'};if(c.stage==='clockout')return {...MANAGER,title:'Clock out with the manager'};const o=ORDERS[c.customer];return {...(c.stage==='brew'?MACHINE:TABLE),title:{order:'Take '+o.name+'’s order',brew:'Prepare '+o.drink,serve:'Serve '+o.name+' · '+o.drink,clean:'Clear the used cup & wipe table'}[c.stage]}}
export function cafeTransaction(state,action,position,place,drink){const c=normalizeCafe(state.cafe),s={...state,cafe:c};const fail=error=>({state:s,error});if(place!=='cafe')return fail('Visit Alder Coffee.');const target=(action==='hire'||action==='clockin')?MANAGER:cafeTask(s);if(Math.hypot(position.x-target.x,position.z-target.z)>1.35)return fail('Move closer to the work station.');
 if(action==='hire'){if(c.employed)return fail('You already work here.');return {state:{...s,cafe:{...c,employed:true}},message:'Hired as café assistant. Talk to the manager to clock in.'}}
 if(action==='clockin'){if(!c.employed||c.stage!=='off')return fail('Talk to the manager first.');if(c.paidDay===s.housing.day||s.routine.shiftDay===s.housing.day)return fail('You have already worked today.');if(s.routine.minutes<480||s.routine.minutes>960)return fail('Clock in between 8 AM and 4 PM.');return {state:{...s,cafe:{...c,stage:'order',customer:0,served:0,day:s.housing.day}},message:'Clocked in · serve two customers, reset their table, then clock out.'}}
 if(!c.employed||c.stage==='off')return fail('Clock in before doing staff work.');if(c.day!==s.housing.day)return fail('This shift has expired. Return to the manager.');
 if(action==='clockout'){if(c.stage!=='clockout')return fail('Finish your assigned customers first.');return {state:{...s,cash:s.cash+2400,routine:{...s.routine,earned:s.routine.earned+2400},cafe:{...c,stage:'off',paidDay:s.housing.day}},message:'Shift complete · 2 customers served · $24.00 wages paid.'}}
 if(action!==c.stage)return fail('Follow the current order.');if(action==='brew'&&drink!==ORDERS[c.customer].drink)return fail('The ticket asks for '+ORDERS[c.customer].drink+'.');
 const next={order:'brew',brew:'serve',serve:'clean',clean:c.customer===0?'order':'clockout'}[action];const updated=advanceTime(s,action==='clean'?15:10);updated.cafe={...c,stage:next,served:c.served+(action==='serve'?1:0),customer:action==='clean'&&c.customer===0?1:c.customer};return {state:updated,message:action==='serve'?'Drink served. Clear the table after your customer leaves.':action==='clean'?'Table ready for the next customer.':action==='brew'?'Drink ready · carry it to the customer.':'Order noted · '+ORDERS[c.customer].drink+'.'};
}
export function expireCafe(s){if(s.cafe.stage!=='off'&&s.cafe.day!==s.housing.day)s.cafe={...s.cafe,stage:'off',served:0,customer:0};return s}
